// export default App;
import './App.css';
import ReactMarkdown from 'react-markdown';
import { GoogleGenAI } from '@google/genai';
import { useState, useEffect, useRef } from 'react';


function App() {
  // Updated with secure API key handling
  const [userInput, setUserInput] = useState('');
  const [chatHistory, setChatHistory] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const messageListRef = useRef(null);
  const micButtonRef = useRef(null);
  const recognitionRef = useRef(null);

  // Initialize AI chat
  const aiRef = useRef(null);
  const chatRef = useRef(null);

  useEffect(() => {
    aiRef.current = new GoogleGenAI({apiKey: process.env.REACT_APP_GEMINI_AI_KEY});
    chatRef.current = aiRef.current.chats.create({
      model: "gemini-2.5-flash",
      history: [
        {
          role: "user",
          parts: [{ text: "Hello" }],
        },
        {
          role: "model",
          parts: [{ text: "Great to meet you. What would you like to know?" }],
        },
      ],
    });
    setChatHistory([{ role: 'model', text: 'Hello! How can I help you today? 😊' }]);
  }, []);

  // Scroll to latest message
  useEffect(() => {
    if (messageListRef.current) {
      messageListRef.current.scrollTop = messageListRef.current.scrollHeight;
    }
  }, [chatHistory]);

  // Speech Recognition setup
  useEffect(() => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) return;

    const recognition = new SpeechRecognition();
    recognition.interimResults = true;
    recognition.lang = 'en-US';
    recognitionRef.current = recognition;

    recognition.onresult = (event) => {
      const transcript = Array.from(event.results)
        .map(result => result[0])
        .map(result => result.transcript)
        .join('');
      setUserInput(transcript);
    };

    recognition.onend = () => {
      setIsRecording(false);
      if (userInput.trim()) {
        handleSendMessage(null, true);
      }
    };

    recognition.onerror = (event) => {
      console.error('Speech recognition error:', event.error);
      if(event.error === 'not-allowed') {
        setChatHistory([{ role: 'model', text: 'Microphone access was denied. Please allow microphone access in your browser settings to use this feature.' }]);
      }
      setIsRecording(false);
    };
  });

  const startRecording = () => {
    if (isRecording || isLoading || !recognitionRef.current) return;
    setIsRecording(true);
    setUserInput('');
    recognitionRef.current.start();
  };

  const stopRecording = () => {
    if (!isRecording || !recognitionRef.current) return;
    setIsRecording(false);
    recognitionRef.current.stop();
  };

  const handleMicClick = () => {
    if (isRecording) {
      stopRecording();
    } else {
      startRecording();
    }
  };

  const handleSendMessage = async (e, fromVoice = false) => {
    if (e) e.preventDefault();
    if (!userInput.trim() || isLoading) return;

    const userMessage = userInput.trim();
    setIsLoading(true);
    setUserInput('');

    setChatHistory(prev => [
      ...prev,
      { role: 'user', text: userMessage },
      { role: 'model', text: '' }
    ]);

    try {
      const stream = await chatRef.current.sendMessageStream({ message: userMessage });
      for await (const chunk of stream) {
        const chunkText = chunk.text;
        setChatHistory(prev => {
          const newHistory = [...prev];
          newHistory[newHistory.length - 1].text += chunkText;
          return newHistory;
        });
      }
    } catch (error) {
      console.error("Error sending message:", error);
      setChatHistory(prev => {
        const newHistory = [...prev];
        newHistory[newHistory.length - 1].text = 'Sorry, something went wrong. Please try again.';
        return newHistory;
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="chat-app" role="main" aria-live="polite">
      <div style={{padding: "16px 20px", fontWeight: "bold", fontSize: "1.2rem", borderBottom: "1px solid #eee", background: "var(--app-background)"}}>
        Voice Enabled AI Assistant
      </div>
      <div className="message-list" ref={messageListRef}>
        {chatHistory.map((msg, index) => (
          <div key={index} className={`message ${msg.role}`}>
            {msg.role === 'model'
              ? <ReactMarkdown>{msg.text}</ReactMarkdown>
              : msg.text}
          </div>
        ))}
        {isLoading && <div className="loading-indicator"></div>}
      </div>
      <form className="chat-form" onSubmit={handleSendMessage}>
        <input
          type="text"
          className="chat-input"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          placeholder={isRecording ? "Listening..." : "Type your message..."}
          aria-label="Chat input"
          disabled={isLoading}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
              handleSendMessage(e);
            }
          }}
        />
        <button
          type="button"
          className={`mic-button${isRecording ? ' recording' : ''}`}
          aria-label={isRecording ? "Stop recording" : "Start recording"}
          onClick={handleMicClick}
          ref={micButtonRef}
          disabled={isLoading}
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z"></path>
            <path d="M19 10v2a7 7 0 0 1-14 0v-2"></path>
            <line x1="12" y1="19" x2="12" y2="22"></line>
          </svg>
        </button>
        <button type="submit" className="send-button" disabled={isLoading || !userInput.trim()} aria-label="Send message">
          &#x27A4;
        </button>
      </form>
    </div>
  );
}

export default App;
